START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261025205257_AddStartingPoints') THEN
    CREATE TABLE "StartingPoints" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(120) NOT NULL,
        "OwnerUserId" text NOT NULL,
        "SourceName" character varying(200),
        "SetupJson" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_StartingPoints" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_StartingPoints_AspNetUsers_OwnerUserId" FOREIGN KEY ("OwnerUserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261025205257_AddStartingPoints') THEN
    CREATE INDEX "IX_StartingPoints_OwnerUserId" ON "StartingPoints" ("OwnerUserId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261025205257_AddStartingPoints') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261025205257_AddStartingPoints', '10.0.8');
    END IF;
END $EF$;
COMMIT;

